def matches(rule, port):
    if rule["port"] == "*":
        return True
    return rule["port"] == port

def evaluate(rules, port):
    for rule in sorted(rules, key=lambda r: r["priority"]):
        if matches(rule, port):
            return rule["priority"], rule["action"]
    return None

rules = [
    {"priority": 100, "port": 443, "action": "Allow"},
    {"priority": 150, "port": "*", "action": "Deny"},
    {"priority": 200, "port": 22, "action": "Allow"},
]

for port in (443, 22):
    priority, action = evaluate(rules, port)
    print(f"Puerto {port}: regla de prioridad {priority} -> {action}")
